PREFIXO_PUBLICACAO_LEGADO = '[Publicação institucional]'


def migrar_publicacoes_legadas(apps, schema_editor):
    """Publicações antigas eram marcadas só pelo prefixo do parecer."""
    RevisaoGovernanca = apps.get_model('core', 'RevisaoGovernanca')
    Processo = apps.get_model('core', 'Processo')

    legadas = RevisaoGovernanca.objects.filter(parecer__startswith=PREFIXO_PUBLICACAO_LEGADO)
    for revisao in legadas.order_by('criado_em'):
        revisao.etapa = 'coordenacao'
        revisao.parecer = revisao.parecer[len(PREFIXO_PUBLICACAO_LEGADO):].strip()
        revisao.save(update_fields=['etapa', 'parecer'])
        Processo.objects.filter(pk=revisao.processo_id, status='publicado').update(
            publicado_por_id=revisao.revisor_id,
            publicado_em=revisao.criado_em,
        )


